INSERT INTO "term_adjudications" ("adjudication_id", "observation_id", "outcome", "term_id", "rationale", "created_at", "created_by_session", "updated_at", "updated_by_session") VALUES (78, 88, 'NAMES-EXISTING', 'TERM-089', 'Supersedes adjudication 77 (DEFERRED), whose stated ground, that the binding provision was not read, was wrong: the persisted ALM 2 text (BFS 2011:5, PDF p. 4) carries 8 § directly above the Allmänt råd, and it reads ''På dessa platser ska delar av nivåskillnaderna utjämnas med ramp till 0-nivå''. The levelling ''till 0-nivå'' is made with a ramp, and the advisory then bounds that ramp''s slope (1:12) and width (90-100 cm), at crossings, parking spaces and boarding places. That is the ramp element in its curb-ramp class, a narrower phrase adjudicated to TERM-089 as ''curb ramp'' was (adjudication 61) and ''short ramps'' (adjudication 63); its slope is TERM-001.', '2026-10-02 02:46', 'session_2026-10-01-research-batch-23', '2026-10-02 02:46', 'session_2026-10-01-research-batch-23');